// Original, optional Fieldguide planning questions. Never an assessment or ranking input.
export const interestRoles=[['study','Study this as a possible main subject'],['both','Study some of it alongside another subject'],['hobby','Keep it as an activity or hobby'],['try','Try a little before deciding'],['unsure','I’m unsure']];
export const preparationChoices=[['open','Keep the routes open / unsure'],['certificate','Compare a college certificate'],['associate','Compare associate and transfer routes'],['bachelor','Compare a bachelor’s route'],['graduate','Understand later graduate or professional study']];
export function freshStudyIntent(){return{version:1,answers:{}};}
export function cleanStudyIntent(value,ids){const out=freshStudyIntent();if(value?.version!==1)return out;for(const id of ids){const raw=value.answers?.[id];if(!raw||typeof raw!=='object')continue;const answer={};for(const[field,options]of [['role',interestRoles],['route',preparationChoices]])if(options.some(([key])=>key===raw[field]))answer[field]=raw[field];if(Object.keys(answer).length)out.answers[id]=answer;}return out;}
export function setStudyIntent(state,pathId,field,value,ids){if(!ids.includes(pathId)||!['role','route'].includes(field))return false;const options=field==='role'?interestRoles:preparationChoices;if(value!==''&&!options.some(([key])=>key===value))return false;const answer={...state.answers[pathId]};if(value==='')delete answer[field];else answer[field]=value;if(Object.keys(answer).length)state.answers[pathId]=answer;else delete state.answers[pathId];return true;}
export const roleLabel=value=>interestRoles.find(([key])=>key===value)?.[1]||'Not answered yet';
export const preparationLabel=value=>preparationChoices.find(([key])=>key===value)?.[1]||'Not answered yet';
